CREATE OR REPLACE FUNCTION room_next_row_version() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.row_version := 1;
RETURN NEW;
END IF;
    NEW.row_version := OLD.row_version;
    IF NEW IS DISTINCT FROM OLD THEN
        NEW.row_version := OLD.row_version + 1;
END IF;
RETURN NEW;
END
$$

CREATE OR REPLACE FUNCTION room_save_version() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        INSERT INTO room_version (room_id, version, operation, data, db_user, client_app)
        VALUES (OLD.id, OLD.row_version + 1, TG_OP, to_jsonb(OLD), current_user,
                current_setting('application_name'));
RETURN NULL;
END IF;
    IF TG_OP = 'UPDATE' AND NEW.row_version = OLD.row_version THEN
        RETURN NULL;
END IF;
INSERT INTO room_version (room_id, version, operation, data, db_user, client_app)
VALUES (NEW.id, NEW.row_version, TG_OP, to_jsonb(NEW), current_user,
        current_setting('application_name'));
RETURN NULL;
END
$$
